mapper.insert:
INSERT INTO system_config (config_key, config_value, category, label, description, value_type, is_sensitive, is_restart_required, sort_order) SELECT src.* FROM ( VALUES
(#{item.configKey}, #{item.configValue}, #{item.category}, #{item.label}, #{item.description}, #{item.valueType}, #{item.isSensitive}, #{item.isRestartRequired}, #{item.sortOrder})
) AS src (config_key, config_value, category, label, description, value_type, is_sensitive, is_restart_required, sort_order) LEFT JOIN system_config t ON t.config_key = src.config_key WHERE t.config_key IS NULL
